import { Component, computed, inject, input, OnInit, output, signal } from '@angular/core';
import { PdfSignService } from '../../services/pdf-sign.service';
import { SignMetadata, WrongPasswordError } from '../../utils/pdf-sign.util';

export interface DocumentoAFirmar {
  nombre: string;
  bytes: Uint8Array;
  clave?: string;
}

export interface ResultadoFirma {
  nombre: string;
  signedBytes: Uint8Array;
  serial: string;
  clave?: string;
}

type DocItemState = 'pending' | 'signing' | 'locked' | 'failed';

interface DocItem {
  nombre: string;
  clave: string;
  bytes: Uint8Array;
  state: DocItemState;
  resultado?: ResultadoFirma;
}

@Component({
  selector: 'app-firma-efirma-modal',
  templateUrl: './firma-efirma-modal.component.html',
  host: { class: 'd-block' },
})
export class FirmaEfirmaModalComponent implements OnInit {
  private readonly pdfSignService = inject(PdfSignService);

  readonly documentos = input.required<DocumentoAFirmar[]>();
  readonly signedClaves = input<string[]>([]);
  readonly metadata = input<SignMetadata>();
  readonly cerrado = output<void>();
  readonly firmado = output<ResultadoFirma[]>();

  readonly cerFileName = signal('');
  readonly keyFileName = signal('');
  readonly password = signal('');
  readonly errorMsg = signal<string | null>(null);

  readonly docItems = signal<DocItem[]>([]);
  readonly firmando = computed(() => this.docItems().some(d => d.state === 'signing'));
  readonly allLocked = computed(() => {
    const items = this.docItems();
    return items.length > 0 && items.every(d => d.state === 'locked');
  });

  readonly modo = signal<'config' | 'signing' | 'success'>('config');

  cerPem: Uint8Array | null = null;
  keyPemEncrypted: Uint8Array | null = null;

  ngOnInit(): void {
    const docs = this.documentos();
    const signed = this.signedClaves();
    this.docItems.set(docs.map(d => ({
      nombre: d.nombre,
      clave: d.clave ?? '',
      bytes: d.bytes,
      state: signed.includes(d.clave ?? '') ? 'locked' : 'pending',
    })));
  }

  onCerSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) return;
    this.cerFileName.set(file.name);
    const reader = new FileReader();
    reader.onload = () => {
      this.cerPem = new Uint8Array(reader.result as ArrayBuffer);
    };
    reader.readAsArrayBuffer(file);
  }

  onKeySelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) return;
    this.keyFileName.set(file.name);
    const reader = new FileReader();
    reader.onload = () => {
      this.keyPemEncrypted = new Uint8Array(reader.result as ArrayBuffer);
    };
    reader.readAsArrayBuffer(file);
  }

  async firmarDocumentos(): Promise<void> {
    if (!this.cerPem || !this.keyPemEncrypted || !this.password()) return;

    const docs = this.documentos();
    if (docs.length === 0) return;

    this.modo.set('signing');
    this.errorMsg.set(null);

    await this.procesarSiguiente();
  }

  async reintentar(index: number): Promise<void> {
    this.errorMsg.set(null);
    await this.firmarDoc(index);
    if (this.docItems()[index].state === 'locked') {
      await this.procesarSiguiente();
    }
  }

  continuar(): void {
    const resultados = this.docItems()
      .filter(d => d.resultado)
      .map(d => d.resultado!);
    this.firmado.emit(resultados);
    this.reset();
    this.cerrado.emit();
  }

  cerrar(): void {
    if (this.firmando()) return;
    this.reset();
    this.cerrado.emit();
  }

  onBackdropClick(event: Event): void {
    if ((event.target as HTMLElement).classList.contains('modal')) {
      this.cerrar();
    }
  }

  private async procesarSiguiente(): Promise<void> {
    const items = this.docItems();
    const nextIndex = items.findIndex(d => d.state === 'pending');

    if (nextIndex === -1) {
      if (this.allLocked()) {
        this.modo.set('success');
      }
      return;
    }

    await this.firmarDoc(nextIndex);
    if (this.docItems()[nextIndex].state === 'locked') {
      await this.procesarSiguiente();
    }
  }

  private async firmarDoc(index: number): Promise<void> {
    const items = [...this.docItems()];
    items[index] = { ...items[index], state: 'signing' };
    this.docItems.set(items);

    const docs = this.documentos();
    const doc = docs[index];

    try {
      const startTime = Date.now();
      const resultado = await this.pdfSignService.sign(
        doc.bytes,
        this.cerPem!,
        this.keyPemEncrypted!,
        this.password(),
        this.metadata(),
      );

      const elapsed = Date.now() - startTime;
      if (elapsed < 1500) {
        await this.delay(1500 - elapsed);
      }

      const updated = [...this.docItems()];
      updated[index] = {
        ...updated[index],
        state: 'locked',
        resultado: {
          nombre: doc.nombre,
          signedBytes: resultado.signedBytes,
          serial: resultado.serial,
          clave: doc.clave,
        },
      };
      this.docItems.set(updated);
    } catch (err: unknown) {
      if (err instanceof WrongPasswordError) {
        this.errorMsg.set('La contraseña es incorrecta o el archivo de llave es inválido.');
      } else {
        const message = err instanceof Error ? err.message : String(err);
        this.errorMsg.set(`Error al firmar: ${message}`);
      }

      const updated = [...this.docItems()];
      updated[index] = { ...updated[index], state: 'failed' };
      this.docItems.set(updated);
    }
  }

  private reset(): void {
    this.modo.set('config');
    this.cerFileName.set('');
    this.keyFileName.set('');
    this.password.set('');
    this.cerPem = null;
    this.keyPemEncrypted = null;
    this.errorMsg.set(null);
    this.docItems.set([]);
  }

  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}
