import { PDFDocument, PDFName, PDFString, PDFHexString, StandardFonts, rgb } from 'pdf-lib';
import forge from 'node-forge';

export interface SignMetadata {
  solicitudId?: number | null;
  resolucionId?: number | null;
  rfc: string;
  createdAt: string;
}

export interface SignedPdfResult {
  signedBytes: Uint8Array;
  serial: string;
}

export class WrongPasswordError extends Error {
  constructor() {
    super('No se pudo descifrar la llave privada con la contraseña proporcionada.');
    this.name = 'WrongPasswordError';
  }
}

const CONTENTS_HEX_LEN = 8192;
const CONTENTS_HEX_PLACEHOLDER = '0'.repeat(CONTENTS_HEX_LEN);

export async function signPdf(
  unsignedPdf: Uint8Array,
  cerPem: string | Uint8Array,
  keyPemEncrypted: string | Uint8Array,
  password: string,
  metadata?: SignMetadata,
): Promise<SignedPdfResult> {
  const normalizedKey = normalizePem(keyPemEncrypted, 'key');
  const normalizedCert = normalizePem(cerPem, 'cert');

  let privateKey: ReturnType<typeof forge.pki.decryptRsaPrivateKey>;
  try {
    privateKey = forge.pki.decryptRsaPrivateKey(normalizedKey, forge.util.encodeUtf8(password) as string);
  } catch {
    throw new WrongPasswordError();
  }
  if (!privateKey) {
    throw new WrongPasswordError();
  }
  const cert = forge.pki.certificateFromPem(normalizedCert);
  const serial = cert.serialNumber;

  const pdfDoc = await PDFDocument.load(unsignedPdf);

  const lastPage = pdfDoc.getPages().at(-1);
  if (lastPage) {
    const boldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
    const footerText = `cadena de firma: ${serial}`;
    lastPage.drawText(footerText, {
      x: 50,
      y: metadata ? 45 : 30,
      size: 9,
      font: boldFont,
      color: rgb(0, 0, 0),
    });

    if (metadata) {
      const parts: string[] = [];
      if (metadata.resolucionId) {
        parts.push(`Resolución ID: ${metadata.resolucionId}`);
      }
      if (metadata.solicitudId) {
        parts.push(`Solicitud ID: ${metadata.solicitudId}`);
      }
      parts.push(`RFC: ${metadata.rfc}`);
      parts.push(`Fecha: ${metadata.createdAt}`);
      const metadataText = parts.join(' | ');
      lastPage.drawText(metadataText, {
        x: 50,
        y: 30,
        size: 8,
        font: boldFont,
        color: rgb(0, 0, 0),
      });
    }
  }

  const sigDict = pdfDoc.context.obj({
    Type: 'Sig',
    SubFilter: 'ETSI.CAdES.detached',
    ByteRange: [0, 0, 0, 0],
    Contents: PDFHexString.of(CONTENTS_HEX_PLACEHOLDER),
  });
  const sigRef = pdfDoc.context.register(sigDict);

  const widget = pdfDoc.context.obj({
    Type: 'Annot',
    Subtype: 'Widget',
    FT: 'Sig',
    T: PDFString.of('Signature1'),
    V: sigRef,
    Rect: [0, 0, 0, 0],
  });
  const widgetRef = pdfDoc.context.register(widget);

  const page = pdfDoc.getPage(0);
  const pageDict = page.node;
  const existingAnnots = pageDict.get(PDFName.of('Annots'));
  if (existingAnnots) {
    (existingAnnots as unknown as { push(ref: unknown): void }).push(widgetRef);
  } else {
    pageDict.set(PDFName.of('Annots'), pdfDoc.context.obj([widgetRef]));
  }

  const acroForm = pdfDoc.context.obj({
    SigFlags: 3,
    Fields: [widgetRef],
  });
  pdfDoc.catalog.set(PDFName.of('AcroForm'), acroForm);

  const pdfBytes = await pdfDoc.save({ useObjectStreams: false });

  const hexPattern = `/Contents <${CONTENTS_HEX_PLACEHOLDER}>`;
  const hexIdx = indexOfBytes(pdfBytes, latin1Encode(hexPattern));
  if (hexIdx === -1) {
    throw new Error('No se encontró el placeholder de Contents en el PDF.');
  }
  const hexStart = hexIdx + '/Contents <'.length;
  const hexEnd = hexStart + CONTENTS_HEX_LEN;

  const brSearch = '/ByteRange';
  const brSearchIdx = indexOfBytes(pdfBytes, latin1Encode(brSearch));
  if (brSearchIdx === -1) {
    throw new Error('No se encontró ByteRange en el PDF.');
  }

  const brOpenBracket = indexOfBytes(pdfBytes, latin1Encode('['), brSearchIdx);
  const brCloseBracket = indexOfBytes(pdfBytes, latin1Encode(']'), brOpenBracket);
  const brIdx = brSearchIdx;
  const oldBrLen = brCloseBracket + 1 - brSearchIdx;

  let shift = 0;
  let newBrStr = '';

  for (let i = 0; i < 10; i++) {
    const adjHexStart = hexStart + shift;
    const adjHexEnd = hexEnd + shift;
    const adjFileSize = pdfBytes.length + shift;
    newBrStr = `/ByteRange [ 0 ${adjHexStart} ${adjHexEnd} ${adjFileSize - adjHexEnd} ]`;
    const newShift = newBrStr.length - oldBrLen;
    if (newShift === shift) break;
    shift = newShift;
  }

  const newPdfBytes = new Uint8Array(pdfBytes.length + shift);
  newPdfBytes.set(pdfBytes.subarray(0, brIdx), 0);
  newPdfBytes.set(latin1Encode(newBrStr), brIdx);
  newPdfBytes.set(pdfBytes.subarray(brIdx + oldBrLen), brIdx + newBrStr.length);

  const finalHexStart = hexStart + shift;
  const finalHexEnd = hexEnd + shift;

  const region1 = newPdfBytes.subarray(0, finalHexStart);
  const region2 = newPdfBytes.subarray(finalHexEnd);
  const dataToSign = new Uint8Array(region1.length + region2.length);
  dataToSign.set(region1, 0);
  dataToSign.set(region2, region1.length);

  const p7 = (forge.pkcs7 as unknown as { createSignedData(): PKCS7 }).createSignedData();
  p7.content = forge.util.createBuffer(dataToSign as unknown as string);
  p7.addCertificate(cert);
  const authenticatedAttributes: { type: string; value?: unknown }[] = [
    { type: forge.pki.oids['contentType'], value: forge.pki.oids['data'] },
    { type: forge.pki.oids['signingTime'], value: new Date() },
    { type: forge.pki.oids['messageDigest'] },
  ];

  if (metadata) {
    const metadataStr = JSON.stringify({
      solicitudId: metadata.solicitudId ?? null,
      resolucionId: metadata.resolucionId ?? null,
      rfc: metadata.rfc,
      createdAt: metadata.createdAt,
    });
    authenticatedAttributes.push({
      type: '1.2.840.113549.1.9.25.3',
      value: forge.util.createBuffer(metadataStr, 'utf8'),
    });
  }

  (p7 as unknown as { addSigner(opts: unknown): void }).addSigner({
    key: privateKey,
    certificate: cert,
    digestAlgorithm: forge.pki.oids['sha256'],
    authenticatedAttributes,
  });
  p7.sign({ detached: true });

  const pkcs7Der = forge.asn1.toDer(p7.toAsn1()).getBytes();
  const pkcs7Hex = forge.util.binary.hex.encode(pkcs7Der);

  if (pkcs7Hex.length > CONTENTS_HEX_LEN) {
    throw new Error(
      `Firma PKCS#7 excede el espacio reservado: ${pkcs7Hex.length} hex chars > ${CONTENTS_HEX_LEN}`,
    );
  }

  const result = new Uint8Array(newPdfBytes);
  for (let i = 0; i < pkcs7Hex.length; i += 2) {
    result[finalHexStart + i / 2] = parseInt(pkcs7Hex.substring(i, i + 2), 16);
  }

  return { signedBytes: result, serial };
}

function latin1Encode(str: string): Uint8Array {
  const bytes = new Uint8Array(str.length);
  for (let i = 0; i < str.length; i++) {
    bytes[i] = str.charCodeAt(i);
  }
  return bytes;
}

function indexOfBytes(haystack: Uint8Array, needle: Uint8Array, fromIndex = 0): number {
  for (let i = fromIndex; i <= haystack.length - needle.length; i++) {
    let match = true;
    for (let j = 0; j < needle.length; j++) {
      if (haystack[i + j] !== needle[j]) {
        match = false;
        break;
      }
    }
    if (match) return i;
  }
  return -1;
}

function normalizePem(input: string | Uint8Array, kind: 'cert' | 'key'): string {
  if (typeof input === 'string' && input.includes('-----BEGIN')) {
    return input;
  }

  let derBytes: Uint8Array;
  if (input instanceof Uint8Array) {
    derBytes = input;
  } else {
    derBytes = latin1Encode(input);
  }

  const label = kind === 'cert' ? 'CERTIFICATE' : 'ENCRYPTED PRIVATE KEY';
  const base64 = forge.util.binary.base64.encode(derBytes);
  const lines: string[] = [];
  for (let i = 0; i < base64.length; i += 64) {
    lines.push(base64.substring(i, i + 64));
  }
  return `-----BEGIN ${label}-----\n${lines.join('\n')}\n-----END ${label}-----`;
}

interface PKCS7 {
  content: ReturnType<typeof forge.util.createBuffer>;
  addCertificate(cert: ReturnType<typeof forge.pki.certificateFromPem>): void;
  sign(options: { detached: boolean }): void;
  toAsn1(): ReturnType<typeof forge.asn1.create>;
}
